-- Runs every data quality test of one layer, logs the failure
-- counts to ops.DataQualityResult and throws when an error-severity
-- test fails, which stops the pipeline (stale but right beats
-- fresh but wrong).
-- Generated by `python -m fde render` from every spec under models/. Do not edit: change the spec and render again.

CREATE OR ALTER PROCEDURE [ops].[RunDataQualityTests]
    @Layer varchar(10),
    @LoadStepID varchar(36)
AS
BEGIN
    SET NOCOUNT ON;

    IF @Layer = 'source'
    BEGIN
        -- policy_admin.policy: freshness_warn___ingested_at
        INSERT INTO [ops].[DataQualityResult] ([LoadStepID], [Layer], [TableName],
            [TestName], [Severity], [FailureCount], [TestedTimestamp])
        SELECT @LoadStepID, 'source', 'policy_admin.policy', 'freshness_warn___ingested_at', 'warn',
            COUNT(*), SYSUTCDATETIME()
        FROM (select latest from (select max([_ingested_at]) as latest from [lh_bronze].[policy_admin].[policy]) as newest where latest is null or datediff(hour, latest, sysutcdatetime()) > 26) AS failing;
        -- policy_admin.policy: freshness_error___ingested_at
        INSERT INTO [ops].[DataQualityResult] ([LoadStepID], [Layer], [TableName],
            [TestName], [Severity], [FailureCount], [TestedTimestamp])
        SELECT @LoadStepID, 'source', 'policy_admin.policy', 'freshness_error___ingested_at', 'error',
            COUNT(*), SYSUTCDATETIME()
        FROM (select latest from (select max([_ingested_at]) as latest from [lh_bronze].[policy_admin].[policy]) as newest where latest is null or datediff(hour, latest, sysutcdatetime()) > 48) AS failing;
        -- policy_admin.agent: freshness_warn___ingested_at
        INSERT INTO [ops].[DataQualityResult] ([LoadStepID], [Layer], [TableName],
            [TestName], [Severity], [FailureCount], [TestedTimestamp])
        SELECT @LoadStepID, 'source', 'policy_admin.agent', 'freshness_warn___ingested_at', 'warn',
            COUNT(*), SYSUTCDATETIME()
        FROM (select latest from (select max([_ingested_at]) as latest from [lh_bronze].[policy_admin].[agent]) as newest where latest is null or datediff(hour, latest, sysutcdatetime()) > 26) AS failing;
        -- policy_admin.agent: freshness_error___ingested_at
        INSERT INTO [ops].[DataQualityResult] ([LoadStepID], [Layer], [TableName],
            [TestName], [Severity], [FailureCount], [TestedTimestamp])
        SELECT @LoadStepID, 'source', 'policy_admin.agent', 'freshness_error___ingested_at', 'error',
            COUNT(*), SYSUTCDATETIME()
        FROM (select latest from (select max([_ingested_at]) as latest from [lh_bronze].[policy_admin].[agent]) as newest where latest is null or datediff(hour, latest, sysutcdatetime()) > 48) AS failing;
    END;

    IF @Layer = 'silver'
    BEGIN
        -- policy_admin.Agent: not_null__Agent_BK
        INSERT INTO [ops].[DataQualityResult] ([LoadStepID], [Layer], [TableName],
            [TestName], [Severity], [FailureCount], [TestedTimestamp])
        SELECT @LoadStepID, 'silver', 'policy_admin.Agent', 'not_null__Agent_BK', 'error',
            COUNT(*), SYSUTCDATETIME()
        FROM (select [Agent_BK] from [lh_silver].[policy_admin].[agent] where [Agent_BK] is null) AS failing;
        -- policy_admin.Agent: unique__Agent_BK
        INSERT INTO [ops].[DataQualityResult] ([LoadStepID], [Layer], [TableName],
            [TestName], [Severity], [FailureCount], [TestedTimestamp])
        SELECT @LoadStepID, 'silver', 'policy_admin.Agent', 'unique__Agent_BK', 'error',
            COUNT(*), SYSUTCDATETIME()
        FROM (select [Agent_BK] from [lh_silver].[policy_admin].[agent] where [Agent_BK] is not null group by [Agent_BK] having count(*) > 1) AS failing;
        -- policy_admin.Policy: not_null__Policy_BK
        INSERT INTO [ops].[DataQualityResult] ([LoadStepID], [Layer], [TableName],
            [TestName], [Severity], [FailureCount], [TestedTimestamp])
        SELECT @LoadStepID, 'silver', 'policy_admin.Policy', 'not_null__Policy_BK', 'error',
            COUNT(*), SYSUTCDATETIME()
        FROM (select [Policy_BK] from [lh_silver].[policy_admin].[policy] where [Policy_BK] is null) AS failing;
        -- policy_admin.Policy: unique__Policy_BK
        INSERT INTO [ops].[DataQualityResult] ([LoadStepID], [Layer], [TableName],
            [TestName], [Severity], [FailureCount], [TestedTimestamp])
        SELECT @LoadStepID, 'silver', 'policy_admin.Policy', 'unique__Policy_BK', 'error',
            COUNT(*), SYSUTCDATETIME()
        FROM (select [Policy_BK] from [lh_silver].[policy_admin].[policy] where [Policy_BK] is not null group by [Policy_BK] having count(*) > 1) AS failing;
        -- policy_admin.Policy: accepted_values__PolicyStatusCode
        INSERT INTO [ops].[DataQualityResult] ([LoadStepID], [Layer], [TableName],
            [TestName], [Severity], [FailureCount], [TestedTimestamp])
        SELECT @LoadStepID, 'silver', 'policy_admin.Policy', 'accepted_values__PolicyStatusCode', 'error',
            COUNT(*), SYSUTCDATETIME()
        FROM (select [PolicyStatusCode] from [lh_silver].[policy_admin].[policy] where [PolicyStatusCode] is not null and [PolicyStatusCode] not in ('IF', 'LA', 'UNKNOWN')) AS failing;
        -- policy_admin.Policy: accepted_range__AnnualPremiumAmount
        INSERT INTO [ops].[DataQualityResult] ([LoadStepID], [Layer], [TableName],
            [TestName], [Severity], [FailureCount], [TestedTimestamp])
        SELECT @LoadStepID, 'silver', 'policy_admin.Policy', 'accepted_range__AnnualPremiumAmount', 'error',
            COUNT(*), SYSUTCDATETIME()
        FROM (select [AnnualPremiumAmount] from [lh_silver].[policy_admin].[policy] where [AnnualPremiumAmount] < 0) AS failing;
        -- policy_admin.Policy: expression__table_1
        INSERT INTO [ops].[DataQualityResult] ([LoadStepID], [Layer], [TableName],
            [TestName], [Severity], [FailureCount], [TestedTimestamp])
        SELECT @LoadStepID, 'silver', 'policy_admin.Policy', 'expression__table_1', 'error',
            COUNT(*), SYSUTCDATETIME()
        FROM (select * from [lh_silver].[policy_admin].[policy] where not (IssueDate is null or IssueDate >= ApplicationDate)) AS failing;
        -- sales.NewBusinessPolicy: not_null__Policy_BK
        INSERT INTO [ops].[DataQualityResult] ([LoadStepID], [Layer], [TableName],
            [TestName], [Severity], [FailureCount], [TestedTimestamp])
        SELECT @LoadStepID, 'silver', 'sales.NewBusinessPolicy', 'not_null__Policy_BK', 'error',
            COUNT(*), SYSUTCDATETIME()
        FROM (select [Policy_BK] from [lh_silver].[sales].[newbusinesspolicy] where [Policy_BK] is null) AS failing;
        -- sales.NewBusinessPolicy: unique__Policy_BK
        INSERT INTO [ops].[DataQualityResult] ([LoadStepID], [Layer], [TableName],
            [TestName], [Severity], [FailureCount], [TestedTimestamp])
        SELECT @LoadStepID, 'silver', 'sales.NewBusinessPolicy', 'unique__Policy_BK', 'error',
            COUNT(*), SYSUTCDATETIME()
        FROM (select [Policy_BK] from [lh_silver].[sales].[newbusinesspolicy] where [Policy_BK] is not null group by [Policy_BK] having count(*) > 1) AS failing;
    END;

    IF @Layer = 'gold'
    BEGIN
        -- distribution.DimAgent: not_null__Agent_BK
        INSERT INTO [ops].[DataQualityResult] ([LoadStepID], [Layer], [TableName],
            [TestName], [Severity], [FailureCount], [TestedTimestamp])
        SELECT @LoadStepID, 'gold', 'distribution.DimAgent', 'not_null__Agent_BK', 'error',
            COUNT(*), SYSUTCDATETIME()
        FROM (select [Agent_BK] from [distribution].[DimAgent] where [Agent_BK] is null) AS failing;
        -- distribution.DimAgent: one_current_row__Agent_BK
        INSERT INTO [ops].[DataQualityResult] ([LoadStepID], [Layer], [TableName],
            [TestName], [Severity], [FailureCount], [TestedTimestamp])
        SELECT @LoadStepID, 'gold', 'distribution.DimAgent', 'one_current_row__Agent_BK', 'error',
            COUNT(*), SYSUTCDATETIME()
        FROM (select [Agent_BK] from [distribution].[DimAgent] group by [Agent_BK] having sum(case when [IsCurrent] = 1 then 1 else 0 end) <> 1) AS failing;
        -- distribution.DimAgent: no_overlapping_versions__Agent_BK
        INSERT INTO [ops].[DataQualityResult] ([LoadStepID], [Layer], [TableName],
            [TestName], [Severity], [FailureCount], [TestedTimestamp])
        SELECT @LoadStepID, 'gold', 'distribution.DimAgent', 'no_overlapping_versions__Agent_BK', 'error',
            COUNT(*), SYSUTCDATETIME()
        FROM (select earlier.[DimAgent_SK] from [distribution].[DimAgent] as earlier inner join [distribution].[DimAgent] as later on earlier.[Agent_BK] = later.[Agent_BK] and earlier.[DimAgent_SK] < later.[DimAgent_SK] and earlier.[StartDate] <= later.[EndDate] and later.[StartDate] <= earlier.[EndDate]) AS failing;
        -- distribution.DimAgent: expression__table
        INSERT INTO [ops].[DataQualityResult] ([LoadStepID], [Layer], [TableName],
            [TestName], [Severity], [FailureCount], [TestedTimestamp])
        SELECT @LoadStepID, 'gold', 'distribution.DimAgent', 'expression__table', 'error',
            COUNT(*), SYSUTCDATETIME()
        FROM (select * from [distribution].[DimAgent] where not (StartDate <= EndDate)) AS failing;
        -- distribution.DimAgent: not_null__DimAgent_SK
        INSERT INTO [ops].[DataQualityResult] ([LoadStepID], [Layer], [TableName],
            [TestName], [Severity], [FailureCount], [TestedTimestamp])
        SELECT @LoadStepID, 'gold', 'distribution.DimAgent', 'not_null__DimAgent_SK', 'error',
            COUNT(*), SYSUTCDATETIME()
        FROM (select [DimAgent_SK] from [distribution].[DimAgent] where [DimAgent_SK] is null) AS failing;
        -- distribution.DimAgent: unique__DimAgent_SK
        INSERT INTO [ops].[DataQualityResult] ([LoadStepID], [Layer], [TableName],
            [TestName], [Severity], [FailureCount], [TestedTimestamp])
        SELECT @LoadStepID, 'gold', 'distribution.DimAgent', 'unique__DimAgent_SK', 'error',
            COUNT(*), SYSUTCDATETIME()
        FROM (select [DimAgent_SK] from [distribution].[DimAgent] where [DimAgent_SK] is not null group by [DimAgent_SK] having count(*) > 1) AS failing;
        -- sales.FactNewBusiness: not_null__Policy_BK
        INSERT INTO [ops].[DataQualityResult] ([LoadStepID], [Layer], [TableName],
            [TestName], [Severity], [FailureCount], [TestedTimestamp])
        SELECT @LoadStepID, 'gold', 'sales.FactNewBusiness', 'not_null__Policy_BK', 'error',
            COUNT(*), SYSUTCDATETIME()
        FROM (select [Policy_BK] from [sales].[FactNewBusiness] where [Policy_BK] is null) AS failing;
        -- sales.FactNewBusiness: unique__Policy_BK
        INSERT INTO [ops].[DataQualityResult] ([LoadStepID], [Layer], [TableName],
            [TestName], [Severity], [FailureCount], [TestedTimestamp])
        SELECT @LoadStepID, 'gold', 'sales.FactNewBusiness', 'unique__Policy_BK', 'error',
            COUNT(*), SYSUTCDATETIME()
        FROM (select [Policy_BK] from [sales].[FactNewBusiness] where [Policy_BK] is not null group by [Policy_BK] having count(*) > 1) AS failing;
        -- sales.FactNewBusiness: not_null__FactNewBusiness_SK
        INSERT INTO [ops].[DataQualityResult] ([LoadStepID], [Layer], [TableName],
            [TestName], [Severity], [FailureCount], [TestedTimestamp])
        SELECT @LoadStepID, 'gold', 'sales.FactNewBusiness', 'not_null__FactNewBusiness_SK', 'error',
            COUNT(*), SYSUTCDATETIME()
        FROM (select [FactNewBusiness_SK] from [sales].[FactNewBusiness] where [FactNewBusiness_SK] is null) AS failing;
        -- sales.FactNewBusiness: unique__FactNewBusiness_SK
        INSERT INTO [ops].[DataQualityResult] ([LoadStepID], [Layer], [TableName],
            [TestName], [Severity], [FailureCount], [TestedTimestamp])
        SELECT @LoadStepID, 'gold', 'sales.FactNewBusiness', 'unique__FactNewBusiness_SK', 'error',
            COUNT(*), SYSUTCDATETIME()
        FROM (select [FactNewBusiness_SK] from [sales].[FactNewBusiness] where [FactNewBusiness_SK] is not null group by [FactNewBusiness_SK] having count(*) > 1) AS failing;
        -- sales.FactNewBusiness: not_null__DimAgent_SK
        INSERT INTO [ops].[DataQualityResult] ([LoadStepID], [Layer], [TableName],
            [TestName], [Severity], [FailureCount], [TestedTimestamp])
        SELECT @LoadStepID, 'gold', 'sales.FactNewBusiness', 'not_null__DimAgent_SK', 'error',
            COUNT(*), SYSUTCDATETIME()
        FROM (select [DimAgent_SK] from [sales].[FactNewBusiness] where [DimAgent_SK] is null) AS failing;
        -- sales.FactNewBusiness: relationships__DimAgent_SK
        INSERT INTO [ops].[DataQualityResult] ([LoadStepID], [Layer], [TableName],
            [TestName], [Severity], [FailureCount], [TestedTimestamp])
        SELECT @LoadStepID, 'gold', 'sales.FactNewBusiness', 'relationships__DimAgent_SK', 'error',
            COUNT(*), SYSUTCDATETIME()
        FROM (select child.[DimAgent_SK] from [sales].[FactNewBusiness] as child left join [distribution].[DimAgent] as parent on child.[DimAgent_SK] = parent.[DimAgent_SK] where child.[DimAgent_SK] is not null and parent.[DimAgent_SK] is null) AS failing;
        -- sales.FactNewBusiness: accepted_range__AnnualPremiumAmount
        INSERT INTO [ops].[DataQualityResult] ([LoadStepID], [Layer], [TableName],
            [TestName], [Severity], [FailureCount], [TestedTimestamp])
        SELECT @LoadStepID, 'gold', 'sales.FactNewBusiness', 'accepted_range__AnnualPremiumAmount', 'error',
            COUNT(*), SYSUTCDATETIME()
        FROM (select [AnnualPremiumAmount] from [sales].[FactNewBusiness] where [AnnualPremiumAmount] < 0) AS failing;
        -- sales.FactNewBusiness: row_count_between__table_1
        INSERT INTO [ops].[DataQualityResult] ([LoadStepID], [Layer], [TableName],
            [TestName], [Severity], [FailureCount], [TestedTimestamp])
        SELECT @LoadStepID, 'gold', 'sales.FactNewBusiness', 'row_count_between__table_1', 'warn',
            COUNT(*), SYSUTCDATETIME()
        FROM (select row_count from (select count(*) as row_count from [sales].[FactNewBusiness]) as counted where row_count < 1) AS failing;
    END;

    DECLARE @Failed int = (
        SELECT COUNT(*) FROM [ops].[DataQualityResult]
        WHERE [LoadStepID] = @LoadStepID AND [Layer] = @Layer
            AND [Severity] = 'error' AND [FailureCount] > 0
    );
    IF @Failed > 0
    BEGIN
        DECLARE @Message varchar(400) = CONCAT(@Failed, ' ', @Layer,
            ' data quality test(s) failed. See ops.DataQualityResult',
            ' for LoadStepID ', @LoadStepID, '.');
        THROW 50001, @Message, 1;
    END;
END
GO
